class Solution { fun movesToStamp(stamp:String,target:String):IntArray{val text=target.toCharArray();val done=BooleanArray(target.length-stamp.length+1);val moves=mutableListOf<Int>();var erased=0;while(erased<text.size){var changed=false;for(start in done.indices)if(!done[start]&&canErase(text,stamp,start)){val added=erase(text,start,stamp.length);if(added>0){erased+=added;changed=true;done[start]=true;moves.add(start)}};if(!changed)return intArrayOf()};return moves.asReversed().toIntArray()};private fun canErase(text:CharArray,stamp:String,start:Int):Boolean{var fresh=false;for(i in stamp.indices)if(text[start+i]!='*'){if(text[start+i]!=stamp[i])return false;fresh=true};return fresh};private fun erase(text:CharArray,start:Int,length:Int):Int{var count=0;for(i in 0 until length)if(text[start+i]!='*'){text[start+i]='*';count++};return count} }
